// Simple Asteroid Rush game
// Canvas with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 400;
  const height = canvas.height = canvas.clientHeight || 600;

  // Ship
  const ship = {
    w: 40,
    h: 20,
    x: width / 2 - 20,
    y: height - 30,
    speed: 5,
    color: '#0f0',
  };

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  // Bullets
  const bullets = [];

  // Asteroids
  const asteroids = [];
  let spawnInterval = 2000; // ms
  let lastSpawn = 0;
  let asteroidSpeed = 1.5;
  let lastTime = 0;
  let gameOver = false;

  function spawnAsteroid() {
    const size = Math.random() * 30 + 10;
    const x = Math.random() * (width - size);
    asteroids.push({ x, y: -size, w: size, h: size, speed: asteroidSpeed });
  }

  function update(delta) {
    if (gameOver) return;
    // Ship movement
    if (keys['ArrowLeft']) ship.x -= ship.speed;
    if (keys['ArrowRight']) ship.x += ship.speed;
    ship.x = Math.max(0, Math.min(width - ship.w, ship.x));

    // Shooting
    if (keys[' ']) {
      // Simple rate limit
      if (!ship.lastShot || Date.now() - ship.lastShot > 300) {
        bullets.push({ x: ship.x + ship.w / 2, y: ship.y, w: 2, h: 10, speed: 7 });
        ship.lastShot = Date.now();
      }
    }

    // Update bullets
    for (let i = bullets.length - 1; i >= 0; i--) {
      const b = bullets[i];
      b.y -= b.speed;
      if (b.y + b.h < 0) bullets.splice(i, 1);
    }

    // Spawn asteroids over time
    if (Date.now() - lastSpawn > spawnInterval) {
      spawnAsteroid();
      lastSpawn = Date.now();
      // accelerate spawning
      spawnInterval = Math.max(300, spawnInterval * 0.95);
      asteroidSpeed += 0.05;
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // Check bottom (lose condition)
      if (a.y + a.h >= height) {
        gameOver = true;
      }
    }

    // Collision detection
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      // Ship collision
      if (rectIntersect(a, ship)) {
        gameOver = true;
        break;
      }
      // Bullet collision
      for (let j = bullets.length - 1; j >= 0; j--) {
        const b = bullets[j];
        if (rectIntersect(a, b)) {
          // remove both
          asteroids.splice(i, 1);
          bullets.splice(j, 1);
          break;
        }
      }
    }
  }

  function rectIntersect(r1, r2) {
    return !(r2.x > r1.x + r1.w ||
             r2.x + r2.w < r1.x ||
             r2.y > r1.y + r1.h ||
             r2.y + r2.h < r1.y);
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Ship
    ctx.fillStyle = ship.color;
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // Bullets
    ctx.fillStyle = '#ff0';
    bullets.forEach(b => ctx.fillRect(b.x, b.y, b.w, b.h));
    // Asteroids
    ctx.fillStyle = '#888';
    asteroids.forEach(a => ctx.fillRect(a.x, a.y, a.w, a.h));
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#f00';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  function loop(timestamp) {
    const delta = timestamp - lastTime;
    lastTime = timestamp;
    update(delta);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // Start the game loop
  requestAnimationFrame(loop);
})();
